package com.dreamcore.workspace.departure;
import com.dreamcore.workspace.identity.*;import com.dreamcore.workspace.governance.GovernanceAccess;import com.dreamcore.workspace.material.MaterialAccess;import com.dreamcore.workspace.retention.RetentionService;import com.dreamcore.workspace.retention.RetentionClock;import com.dreamcore.workspace.source.SourceService;
import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.json.JsonMapper;
@Service public class DepartureService {
 public record ExportGrant(UUID accountId,UUID workspaceId){}
 public record ViewGrant(UUID accountId,UUID workspaceId,String workspaceName){}
 public record Member(UUID id,String name,String status,long revision){}
 public record SharedResponsibility(String kind,UUID workspaceId,String workspaceName,UUID objectId,String name,UUID responsibleId,long revision){}
 public record Candidate(UUID id,String name){}
 public record Handover(UUID id,String kind,UUID workspaceId,UUID objectId,UUID fromAccountId,UUID toAccountId,long resultingRevision,Instant createdAt){}
 public record Summary(UUID id,UUID tenantId,String kind,UUID targetAccountId,String state,int revision,Instant effectiveAt,Instant deadline,Instant completedAt,String errorCode){}
 public record View(Summary execution,String targetName,String reason,String policyKey,int policyRevision,boolean stopComplete,boolean isolationComplete,boolean materialsComplete,boolean objectsComplete,Instant cancelledAt,int workerAttempts,String backupState,boolean canCancel,boolean canRetry,List<ViewGrant> exportGrants,DepartureMaterialBridge.Progress materialProgress,List<String> coverage){}
 public record Page(List<Summary> items,boolean hasMore){}
 public record Options(long tenantRevision,List<Member> members,boolean membersHaveMore,List<SharedResponsibility> responsibilities,boolean responsibilitiesHaveMore,boolean canOffboard,boolean canExit,Member selectedMember,boolean selectedOwner,UUID currentExecutionId,long isolationDays){}
 private final JdbcTemplate db;private final IdentityService identities;private final GovernanceAccess governance;private final IdentityAudit audit;private final MaterialAccess material;private final SourceService sources;private final RetentionService retention;private final RetentionClock clock;private final DepartureAccess access;private final DepartureMaterialBridge materials;private final JsonMapper json=new JsonMapper();
 public DepartureService(JdbcTemplate db,IdentityService identities,GovernanceAccess governance,IdentityAudit audit,MaterialAccess material,SourceService sources,RetentionService retention,RetentionClock clock,DepartureAccess access,DepartureMaterialBridge materials){this.db=db;this.identities=identities;this.governance=governance;this.audit=audit;this.material=material;this.sources=sources;this.retention=retention;this.clock=clock;this.access=access;this.materials=materials;}
 private void page(int offset,int limit){if(offset<0||offset>100000||limit<1||limit>50)throw IdentityException.invalid();}
 private Instant time(Map<String,Object>r,String k){return r.get(k)==null?null:((java.sql.Timestamp)r.get(k)).toInstant();}
 private void lock(UUID actor,UUID tenant){identities.member(actor,tenant,false,false);db.queryForList("SELECT id FROM tenants WHERE id=? FOR UPDATE",tenant);identities.member(actor,tenant,false,false);}
 private void require(UUID actor,UUID tenant,String kind){governance.require(actor,tenant,kind.equals("MEMBER_OFFBOARD")?GovernanceAccess.Capability.MEMBER_OFFBOARD:GovernanceAccess.Capability.TENANT_EXIT,null);}
 private boolean allowed(UUID actor,UUID tenant,String kind){return governance.allows(actor,tenant,kind.equals("MEMBER_OFFBOARD")?GovernanceAccess.Capability.MEMBER_OFFBOARD:GovernanceAccess.Capability.TENANT_EXIT,null);}
 private String reason(String s){if(s==null||s.isBlank()||s.length()>500)throw IdentityException.invalid();return s.strip();}
 private Map<String,Object> row(UUID tenant,UUID id){var rows=db.queryForList("SELECT * FROM departure_executions WHERE tenant_id=? AND id=?",tenant,id);if(rows.isEmpty())throw new IdentityException(404,"DEPARTURE_NOT_FOUND");return rows.getFirst();}
 private Summary summary(Map<String,Object>r){return new Summary((UUID)r.get("id"),(UUID)r.get("tenant_id"),(String)r.get("kind"),(UUID)r.get("target_account_id"),(String)r.get("state"),(Integer)r.get("revision"),time(r,"effective_at"),time(r,"deadline"),time(r,"completed_at"),(String)r.get("error_code"));}
 private void event(Map<String,Object>r,String action,UUID actor){db.update("INSERT INTO departure_events(id,execution_id,revision,action,state,actor_id,created_at) VALUES (?,?,?,?,?,?,?)",UUID.randomUUID(),r.get("id"),r.get("revision"),action,r.get("state"),actor,java.sql.Timestamp.from(clock.now()));}
 @Transactional public Options options(UUID actor,UUID tenant,UUID target,int memberOffset,int responsibilityOffset,int limit){identities.member(actor,tenant,false);boolean off=allowed(actor,tenant,"MEMBER_OFFBOARD"),exit=allowed(actor,tenant,"TENANT_EXIT");if(!off&&!exit)throw new IdentityException(403,"CAPABILITY_REQUIRED");page(memberOffset,limit);page(responsibilityOffset,limit);
  var members=db.query("SELECT a.id,a.display_name,m.status,m.management_version FROM tenant_memberships m JOIN accounts a ON a.id=m.account_id WHERE m.tenant_id=? ORDER BY a.display_name,a.id LIMIT ? OFFSET ?",(r,n)->new Member(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getLong(4)),tenant,limit+1,memberOffset);
  Member selected=null;
  if(target!=null){
   if(!off)throw new IdentityException(403,"CAPABILITY_REQUIRED");
   var targets=db.query("SELECT a.id,a.display_name,m.status,m.management_version FROM tenant_memberships m JOIN accounts a ON a.id=m.account_id WHERE m.tenant_id=? AND m.account_id=?",(r,n)->new Member(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getLong(4)),tenant,target);
   if(targets.isEmpty())throw new IdentityException(404,"MEMBER_NOT_FOUND");selected=targets.getFirst();
  }
  var responsibilities=target==null?List.<SharedResponsibility>of():db.query("""
   SELECT * FROM (
    SELECT 'WORKSPACE_OWNER' AS kind,w.id AS workspace_id,w.name AS workspace_name,w.id AS object_id,w.name,w.owner_id AS responsible_id,w.management_version AS revision
     FROM workspaces w JOIN workspace_members g ON g.tenant_id=w.tenant_id AND g.workspace_id=w.id AND g.account_id=? AND g.can_maintain
     WHERE w.tenant_id=? AND w.kind='SHARED' AND departure_content_readable(g.account_id,w.tenant_id,w.id) AND w.owner_id=?
    UNION ALL SELECT 'SOURCE_CONTACT',w.id,w.name,s.id,s.name,s.responsible_id,s.revision FROM business_sources s JOIN workspaces w ON w.id=s.workspace_id
     JOIN workspace_members g ON g.tenant_id=w.tenant_id AND g.workspace_id=w.id AND g.account_id=? AND g.can_maintain
     WHERE s.tenant_id=? AND w.kind='SHARED' AND departure_content_readable(g.account_id,w.tenant_id,w.id) AND s.responsible_id=?
   ) r ORDER BY kind,object_id LIMIT ? OFFSET ?
   """,(r,n)->new SharedResponsibility(r.getString(1),r.getObject(2,UUID.class),r.getString(3),r.getObject(4,UUID.class),r.getString(5),r.getObject(6,UUID.class),r.getLong(7)),actor,tenant,target,actor,tenant,target,limit+1,responsibilityOffset);
  Instant checkedAt=clock.now();
  return new Options(db.queryForObject("SELECT management_version FROM tenants WHERE id=?",Long.class,tenant),members.stream().limit(limit).toList(),members.size()>limit,responsibilities.stream().limit(limit).toList(),responsibilities.size()>limit,off,exit,selected,
   target!=null&&Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM tenant_governance WHERE tenant_id=? AND owner_id=?)",Boolean.class,tenant,target)),
   target==null?null:db.queryForList("SELECT id FROM departure_executions WHERE tenant_id=? AND target_account_id=? AND kind='MEMBER_OFFBOARD' AND state<>'CANCELLED' ORDER BY effective_at DESC LIMIT 1",UUID.class,tenant,target).stream().findFirst().orElse(null),
   java.time.Duration.between(checkedAt,retention.resolveDeadline(tenant,"OFFBOARD_ISOLATION",checkedAt).dueAt()).toDays());
 }
 public record ExportScope(UUID workspaceId,String name){}
 @Transactional public List<ExportScope> exportScopes(UUID actor,UUID tenant,int offset,int limit){return exportScopes(actor,tenant,actor,offset,limit);}
 @Transactional public List<ExportScope> exportScopes(UUID actor,UUID tenant,UUID exporter,int offset,int limit){identities.member(actor,tenant,false);require(actor,tenant,"TENANT_EXIT");page(offset,limit);UUID recipient=exporter==null?actor:exporter;identities.member(recipient,tenant,false);return db.query("SELECT w.id,w.name FROM workspaces w JOIN workspace_members m ON m.tenant_id=w.tenant_id AND m.workspace_id=w.id AND m.account_id=? JOIN workspace_members target ON target.tenant_id=w.tenant_id AND target.workspace_id=w.id AND target.account_id=? WHERE w.tenant_id=? AND w.kind='SHARED' AND departure_content_readable(?,w.tenant_id,w.id) AND departure_content_readable(?,w.tenant_id,w.id) AND EXISTS(SELECT 1 FROM governance_capabilities c WHERE c.tenant_id=w.tenant_id AND c.account_id=? AND c.capability='BULK_EXPORT' AND(c.workspace_id IS NULL OR c.workspace_id=w.id)) ORDER BY w.name,w.id LIMIT ? OFFSET ?",(r,n)->new ExportScope(r.getObject(1,UUID.class),r.getString(2)),actor,recipient,tenant,actor,recipient,recipient,limit,offset);}

 @Transactional public List<Candidate> successors(UUID actor,UUID tenant,UUID workspace,int offset,int limit){require(actor,tenant,"MEMBER_OFFBOARD");page(offset,limit);if(!material.require(actor,tenant,workspace,true).kind().equals("SHARED"))throw IdentityException.invalid();return db.query("SELECT a.id,a.display_name FROM workspace_members g JOIN accounts a ON a.id=g.account_id JOIN tenant_memberships m ON m.tenant_id=g.tenant_id AND m.account_id=g.account_id WHERE g.tenant_id=? AND g.workspace_id=? AND g.can_maintain AND a.status='ACTIVE' AND m.status='ACTIVE' ORDER BY a.display_name,a.id LIMIT ? OFFSET ?",(r,n)->new Candidate(r.getObject(1,UUID.class),r.getString(2)),tenant,workspace,limit,offset);}
 @Transactional public Handover handover(UUID actor,UUID tenant,UUID key,String kind,UUID workspace,UUID object,UUID from,UUID to,long expected){if(!Set.of("WORKSPACE_OWNER","SOURCE_CONTACT").contains(kind==null?"":kind)||workspace==null||object==null||from==null||to==null||from.equals(to)||expected<0)throw IdentityException.invalid();lock(actor,tenant);require(actor,tenant,"MEMBER_OFFBOARD");access.requireActiveBusiness(actor,tenant);String fp=IdentityService.hash(json.writeValueAsString(new Object[]{tenant,kind,workspace,object,from,to,expected}));UUID prior=identities.priorRequest(actor,key,"DEPARTURE_HANDOVER",fp);if(prior!=null)return handoverReceipt(tenant,prior);if(kind.equals("WORKSPACE_OWNER")&&Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM workspaces WHERE tenant_id=? AND id=? AND responsibility_confirmed)",Boolean.class,tenant,workspace)))throw new IdentityException(409,"SPACE_OWNER_USE_MANAGEMENT");if(!material.require(actor,tenant,workspace,true).kind().equals("SHARED"))throw IdentityException.invalid();if(!material.require(to,tenant,workspace,true).kind().equals("SHARED"))throw IdentityException.invalid();long resulting;
  if(kind.equals("WORKSPACE_OWNER")){if(!workspace.equals(object))throw IdentityException.invalid();if(db.update("UPDATE workspaces SET owner_id=?,management_version=management_version+1 WHERE tenant_id=? AND id=? AND kind='SHARED' AND owner_id=? AND management_version=?",to,tenant,workspace,from,expected)!=1)throw new IdentityException(409,"DEPARTURE_REVISION_CONFLICT");resulting=expected+1;}else{var s=sources.get(actor,tenant,workspace,object);if(!s.responsibleId().equals(from)||s.revision()!=expected)throw new IdentityException(409,"DEPARTURE_REVISION_CONFLICT");UUID inner=UUID.nameUUIDFromBytes((key+":source-handover").getBytes(java.nio.charset.StandardCharsets.UTF_8));var updated=sources.update(actor,tenant,workspace,object,inner,(int)expected,new SourceService.Settings(s.name(),s.description(),to,s.cadenceHours(),s.expectedFrom(),s.expectedThrough(),s.status()));resulting=updated.revision();}
  UUID id=UUID.randomUUID();db.update("INSERT INTO departure_handovers(id,tenant_id,workspace_id,object_kind,object_id,from_account_id,to_account_id,actor_id,resulting_revision,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)",id,tenant,workspace,kind,object,from,to,actor,resulting,java.sql.Timestamp.from(clock.now()));identities.remember(actor,key,"DEPARTURE_HANDOVER",fp,id);audit.record(actor,tenant,"DEPARTURE_SHARED_HANDOVER",id,"SUCCESS");return handoverReceipt(tenant,id);
 }
 private Handover handoverReceipt(UUID tenant,UUID id){return db.queryForObject("SELECT * FROM departure_handovers WHERE tenant_id=? AND id=?",(r,n)->new Handover(id,r.getString("object_kind"),r.getObject("workspace_id",UUID.class),r.getObject("object_id",UUID.class),r.getObject("from_account_id",UUID.class),r.getObject("to_account_id",UUID.class),r.getLong("resulting_revision"),r.getTimestamp("created_at").toInstant()),tenant,id);}
 @Transactional public View beginOffboard(UUID actor,UUID tenant,UUID target,UUID key,long expected,String why,boolean acceptCleanup){why=reason(why);if(target==null||target.equals(actor)||expected<0||!acceptCleanup)throw IdentityException.invalid();lock(actor,tenant);require(actor,tenant,"MEMBER_OFFBOARD");String fp=IdentityService.hash(json.writeValueAsString(new Object[]{tenant,target,expected,why,acceptCleanup}));UUID prior=identities.priorRequest(actor,key,"MEMBER_OFFBOARD_EFFECTIVE",fp);if(prior!=null)return view(actor,tenant,row(tenant,prior),true);access.requireActiveBusiness(actor,tenant);var members=db.queryForList("SELECT m.*,a.status AS account_status FROM tenant_memberships m JOIN accounts a ON a.id=m.account_id WHERE m.tenant_id=? AND m.account_id=?",tenant,target);if(members.isEmpty())throw new IdentityException(404,"MEMBER_NOT_FOUND");var member=members.getFirst();if((Long)member.get("management_version")!=expected)throw new IdentityException(409,"DEPARTURE_REVISION_CONFLICT");governance.protectOwner(tenant,target,"DISABLED");if(member.get("role").equals("TENANT_ADMIN")&&member.get("status").equals("ACTIVE")&&db.queryForObject("SELECT count(*) FROM tenant_memberships m JOIN accounts a ON a.id=m.account_id WHERE m.tenant_id=? AND m.account_id<>? AND m.status='ACTIVE' AND m.role='TENANT_ADMIN' AND a.status='ACTIVE'",Integer.class,tenant,target)==0)throw new IdentityException(409,"LAST_TENANT_ADMIN");if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM departure_executions WHERE tenant_id=? AND target_account_id=? AND state<>'CANCELLED')",Boolean.class,tenant,target)))throw new IdentityException(409,"DEPARTURE_ALREADY_EFFECTIVE");
  UUID id=UUID.randomUUID();Instant now=clock.now();var policy=retention.resolveDeadline(tenant,"OFFBOARD_ISOLATION",now);db.update("INSERT INTO departure_executions(id,tenant_id,kind,target_account_id,state,requested_by,reason,policy_key,policy_revision,effective_at,deadline,prior_member_status,stopped_member_version,prior_tenant_status) VALUES (?,?,'MEMBER_OFFBOARD',?,'ISOLATING',?,?,?,?,?,?,?,?, 'ACTIVE')",id,tenant,target,actor,why,policy.policyKey(),policy.policyRevision(),java.sql.Timestamp.from(now),java.sql.Timestamp.from(policy.dueAt()),member.get("status"),expected+1);db.update("UPDATE tenant_memberships SET status='DISABLED',management_version=management_version+1 WHERE tenant_id=? AND account_id=?",tenant,target);db.update("DELETE FROM workspace_members WHERE tenant_id=? AND account_id=?",tenant,target);db.update("DELETE FROM governance_capabilities WHERE tenant_id=? AND account_id=?",tenant,target);db.queryForList("SELECT scrub_export_scope(?,?)",tenant,target);identities.remember(actor,key,"MEMBER_OFFBOARD_EFFECTIVE",fp,id);event(row(tenant,id),"MEMBER_DISABLED",actor);audit.record(actor,tenant,"MEMBER_OFFBOARD_EFFECTIVE",id,"SUCCESS");return view(actor,tenant,row(tenant,id),false);
 }
 @Transactional public View beginExit(UUID actor,UUID tenant,UUID key,long expected,String why,List<ExportGrant> grants,boolean acceptCleanup){why=reason(why);if(expected<0||!acceptCleanup||grants==null||grants.size()>200||grants.stream().anyMatch(g->g==null||g.accountId()==null||g.workspaceId()==null)||new HashSet<>(grants).size()!=grants.size())throw IdentityException.invalid();var ordered=grants.stream().sorted(Comparator.comparing((ExportGrant g)->g.accountId().toString()).thenComparing(g->g.workspaceId().toString())).toList();lock(actor,tenant);require(actor,tenant,"TENANT_EXIT");String fp=IdentityService.hash(json.writeValueAsString(new Object[]{tenant,expected,why,ordered,acceptCleanup}));UUID prior=identities.priorRequest(actor,key,"TENANT_EXIT_EFFECTIVE",fp);if(prior!=null)return view(actor,tenant,row(tenant,prior),true);access.requireActiveBusiness(actor,tenant);if(db.queryForObject("SELECT management_version FROM tenants WHERE id=?",Long.class,tenant)!=expected)throw new IdentityException(409,"DEPARTURE_REVISION_CONFLICT");for(var g:ordered){if(!material.require(g.accountId(),tenant,g.workspaceId(),false).kind().equals("SHARED"))throw new IdentityException(403,"DEPARTURE_SHARED_EXPORT_ONLY");if(!governance.allows(g.accountId(),tenant,GovernanceAccess.Capability.BULK_EXPORT,null)&&!governance.allows(g.accountId(),tenant,GovernanceAccess.Capability.BULK_EXPORT,g.workspaceId()))throw new IdentityException(403,"BULK_EXPORT_REQUIRED");}
  UUID id=UUID.randomUUID();Instant now=clock.now();var policy=retention.resolveDeadline(tenant,"TENANT_EXIT_WINDOW",now);db.update("INSERT INTO departure_executions(id,tenant_id,kind,state,requested_by,reason,policy_key,policy_revision,effective_at,deadline,prior_tenant_status) VALUES (?,?,'TENANT_EXIT','EXPORT_WINDOW',?,?,?,?,?,?,'ACTIVE')",id,tenant,actor,why,policy.policyKey(),policy.policyRevision(),java.sql.Timestamp.from(now),java.sql.Timestamp.from(policy.dueAt()));for(var g:ordered)db.update("INSERT INTO departure_export_grants(execution_id,tenant_id,account_id,workspace_id) VALUES (?,?,?,?)",id,tenant,g.accountId(),g.workspaceId());db.update("UPDATE tenants SET management_version=management_version+1 WHERE id=?",tenant);db.queryForList("SELECT scrub_export_scope(?,NULL::uuid)",tenant);identities.remember(actor,key,"TENANT_EXIT_EFFECTIVE",fp,id);event(row(tenant,id),"EXIT_WINDOW_STARTED",actor);audit.record(actor,tenant,"TENANT_EXIT_EFFECTIVE",id,"SUCCESS");return view(actor,tenant,row(tenant,id),true);
 }
 @Transactional public Page list(UUID actor,UUID tenant,int offset,int limit){return list(actor,tenant,offset,limit,"");}
 @Transactional public Page list(UUID actor,UUID tenant,int offset,int limit,String kind){if(!Set.of("","MEMBER_OFFBOARD","TENANT_EXIT").contains(kind))throw IdentityException.invalid();identities.member(actor,tenant,false);page(offset,limit);boolean off=allowed(actor,tenant,"MEMBER_OFFBOARD"),exit=allowed(actor,tenant,"TENANT_EXIT");var rows=db.queryForList("SELECT * FROM departure_executions e WHERE tenant_id=? AND (?='' OR kind=?) AND ((kind='MEMBER_OFFBOARD' AND ?) OR (kind='TENANT_EXIT' AND (? OR EXISTS(SELECT 1 FROM departure_export_grants g WHERE g.execution_id=e.id AND g.account_id=?)))) ORDER BY effective_at DESC,id LIMIT ? OFFSET ?",tenant,kind,kind,off,exit,actor,limit+1,offset);if(!off&&!exit&&rows.isEmpty())throw new IdentityException(403,"CAPABILITY_REQUIRED");return new Page(rows.stream().limit(limit).map(this::summary).toList(),rows.size()>limit);}
 @Transactional public View get(UUID actor,UUID tenant,UUID id){identities.member(actor,tenant,false);var r=row(tenant,id);if(!allowed(actor,tenant,(String)r.get("kind"))&&!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM departure_export_grants WHERE execution_id=? AND account_id=?)",Boolean.class,id,actor)))throw new IdentityException(403,"CAPABILITY_REQUIRED");return view(actor,tenant,r,true);}
 private View view(UUID actor,UUID tenant,Map<String,Object>r,boolean inspect){String target=null;if(r.get("target_account_id")!=null)target=db.queryForObject("SELECT display_name FROM accounts WHERE id=?",String.class,r.get("target_account_id"));var grants=db.query("SELECT g.account_id,g.workspace_id,CASE WHEN departure_content_readable(g.account_id,g.tenant_id,g.workspace_id) THEN w.name ELSE NULL END AS workspace_name FROM departure_export_grants g JOIN workspaces w ON w.id=g.workspace_id WHERE g.execution_id=? AND g.account_id=? ORDER BY g.workspace_id",(s,n)->new ViewGrant(s.getObject(1,UUID.class),s.getObject(2,UUID.class),s.getString(3)),r.get("id"),actor);boolean canCancel=inspect&&r.get("kind").equals("MEMBER_OFFBOARD")&&Set.of("ISOLATING","ISOLATED").contains(r.get("state"))&&clock.now().isBefore(time(r,"deadline"))&&allowed(actor,tenant,"MEMBER_OFFBOARD");return new View(summary(r),target,(String)r.get("reason"),(String)r.get("policy_key"),(Integer)r.get("policy_revision"),(Boolean)r.get("stop_complete"),(Boolean)r.get("isolation_complete"),(Boolean)r.get("materials_complete"),(Boolean)r.get("objects_complete"),time(r,"cancelled_at"),(Integer)r.get("worker_attempts"),(String)r.get("backup_state"),canCancel,inspect&&allowed(actor,tenant,(String)r.get("kind"))&&!Set.of("COMPLETE","CANCELLED","RESTORING").contains(r.get("state")),grants,inspect?materials.progress((UUID)r.get("id")):null,List.of("正式状态立即阻断受影响身份和新业务；运行中已发生动作不会被宣称自动撤销","离职仅隔离该员工私人内容；共享责任须逐项移交，私人所有权不转给管理员","企业退出仅向明确指定且当前仍获权的人开放所选共享资产迁出；私人内容不进入企业包","截止后直接分批在线清理，不追加普通回收期；COMPLETE只代表已覆盖执行器在线清理完成","备份副本的删除与恢复守卫独立核验，当前保留PENDING_VERIFICATION"));}
 @Transactional public View command(UUID actor,UUID tenant,UUID id,UUID key,int expected,String action){if(expected<1||!Set.of("CANCEL_OFFBOARD","RETRY").contains(action==null?"":action))throw IdentityException.invalid();lock(actor,tenant);var r=row(tenant,id);require(actor,tenant,(String)r.get("kind"));String fp=IdentityService.hash(json.writeValueAsString(new Object[]{tenant,id,expected,action}));UUID prior=identities.priorRequest(actor,key,"DEPARTURE_COMMAND",fp);if(prior!=null)return view(actor,tenant,row(tenant,prior),true);if((Integer)r.get("revision")!=expected)throw new IdentityException(409,"DEPARTURE_REVISION_CONFLICT");if(Set.of("COMPLETE","CANCELLED","RESTORING").contains(r.get("state")))throw new IdentityException(409,"DEPARTURE_STATE_CONFLICT");
  if(action.equals("CANCEL_OFFBOARD")){if(!r.get("kind").equals("MEMBER_OFFBOARD")||!clock.now().isBefore(time(r,"deadline")))throw new IdentityException(409,"DEPARTURE_NOT_RESTORABLE");var member=db.queryForMap("SELECT m.*,a.status account_status FROM tenant_memberships m JOIN accounts a ON a.id=m.account_id WHERE m.tenant_id=? AND m.account_id=?",tenant,r.get("target_account_id"));if(!member.get("account_status").equals("ACTIVE")||!member.get("status").equals("DISABLED")||!member.get("management_version").equals(r.get("stopped_member_version"))||access.exiting(tenant))throw new IdentityException(409,"DEPARTURE_IDENTITY_CHANGED");db.update("UPDATE departure_executions SET state='RESTORING',revision=revision+1,error_code=NULL,checked_at=NULL WHERE id=?",id);}else{db.update("UPDATE departure_executions SET revision=revision+1,error_code=NULL,checked_at=NULL WHERE id=?",id);db.update("UPDATE content_cleanup_jobs SET state='QUEUED',revision=revision+1,error_code=NULL WHERE state='FAILED' AND id IN(SELECT cleanup_job_id FROM departure_materials WHERE execution_id=?)",id);}
  identities.remember(actor,key,"DEPARTURE_COMMAND",fp,id);event(row(tenant,id),action,actor);audit.record(actor,tenant,"DEPARTURE_"+action,id,"SUCCESS");return view(actor,tenant,row(tenant,id),true);
 }
}
